def parse_numeric(value):
    """Extract a numeric value from a string like '25 °C' or '100 mM'.

    Call this ONLY for a single-valued field eLabFTW types as a number. On a text field
    it is destructive - '20 mM NaAc' becomes 20.0 and the buffer identity is gone - and
    on a delimited list it keeps only the first element. When in doubt, store the
    original string unchanged.
    """

    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        text = value.strip()
        import re

        # treat comma as decimal separator if present
        match = re.search(r"[-+]?\d*\.?\d+", text.replace(",", "."))
        if match:
            try:
                return float(match.group())
            except ValueError:
                return None
    return None


def parse_field(value, field_type=None):
    """Route an eLabFTW value by what it IS, not by which parameter it came from.

    Any field may arrive as a delimited list, so the delimiter check comes first.
    """

    if value is None or value == "":
        return None
    if isinstance(value, (list, int, float)):
        return value
    text = str(value).strip()

    # a list if a delimiter separates more than one token; "1,5" (decimal comma) is one
    for sep in (";", ","):
        parts = [p.strip() for p in text.split(sep) if p.strip()]
        if len(parts) > 1:
            # Try to interpret as a single number with decimal comma for comma separator
            if sep == "," and len(parts) == 2:
                joined = "".join(parts)
                try:
                    return float(joined)
                except ValueError:
                    pass
            # Otherwise treat as list
            all_numeric = True
            numeric_vals = []
            for p in parts:
                try:
                    numeric_vals.append(float(p))
                except ValueError:
                    all_numeric = False
                    break
            if all_numeric:
                return numeric_vals
            return parts

    if field_type == "number":
        numeric = parse_numeric(text)
        return numeric if numeric is not None else text

    return text  # text stays text


def find_experiment_json(elab_id):
    """Find experiment JSON file."""

    paths = [
        Path(f"../experiment_{elab_id}.json"),
        Path(f"../data/experiment_{elab_id}.json"),
    ]
    for p in paths:
        if p.exists():
            return p
    raise FileNotFoundError(f"Experiment JSON not found for {elab_id}")


def load_workflow():
    """Load workflow.json and extract lab_id."""

    workflow_path = Path("../workflow.json")
    if workflow_path.exists():
        with open(workflow_path) as f:
            data = json.load(f)
            return data, data.get("lab_id") or data.get("labId")
    return None, None


def extract_metadata(extra_fields):
    """Extract and map metadata from eLabFTW extra fields."""

    metadata = {}
    for elab_name, db_name in FIELD_MAPPING.items():
        if elab_name in extra_fields:
            field = extra_fields.get(elab_name) or {}
            raw_value = field.get("value")
            field_type = field.get("type")
            parsed = parse_field(raw_value, field_type=field_type)
            # Linked process ID is an identifier; always keep as string
            if db_name == "linked_process_id" and parsed is not None:
                metadata[db_name] = str(parsed)
            else:
                metadata[db_name] = parsed
    return metadata


def list_folder_files(folder_path):
    """List files in a folder."""

    folder = Path(folder_path)
    if folder.exists():
        return [f.name for f in folder.iterdir() if f.is_file()]
    return []


def build_raw_data(elab_id):
    """Build raw_data JSONB structure."""

    data_folder = Path("../data")
    return {
        "folder_path": str(data_folder.resolve()),
        "files": list_folder_files(data_folder),
    }


def load_analysis_results(elab_id):
    """Load analysis_results_<ID>.json if present."""

    results_folder = Path("../results")
    analysis_path = results_folder / f"analysis_results_{elab_id}.json"
    if analysis_path.exists():
        try:
            with open(analysis_path, "r") as f:
                return json.load(f)
        except Exception:
            return None
    return None


def build_results(elab_id):
    """Build results JSONB structure from analysis outputs and files."""

    results_folder = Path("../results")
    analysis = load_analysis_results(elab_id) or {}

    # Derive analysis_status
    status = analysis.get("status")
    if status == "success":
        analysis_status = "completed"
    elif status in ("failed", "error"):
        analysis_status = "failed"
    else:
        analysis_status = "pending"

    timestamp = datetime.now(timezone.utc).isoformat()

    # Collect file paths if analysis JSON already recorded them
    data_outputs = analysis.get("data_outputs", {}) or {}
    plots_outputs = analysis.get("plots", {}) or {}

    # Fallback: if expected files exist but are not listed in analysis JSON, add them
    processed_csv = results_folder / f"akta_processed_{elab_id}.csv"
    peaks_csv = results_folder / f"akta_peaks_{elab_id}.csv"
    analysis_json = results_folder / f"analysis_results_{elab_id}.json"
    chromatogram_png = results_folder / f"akta_chromatogram_{elab_id}.png"
    chromatogram_pdf = results_folder / f"akta_chromatogram_{elab_id}.pdf"

    if processed_csv.exists() and "akta_processed_csv" not in data_outputs:
        data_outputs["akta_processed_csv"] = str(processed_csv.resolve())
    if peaks_csv.exists() and "akta_peaks_csv" not in data_outputs:
        data_outputs["akta_peaks_csv"] = str(peaks_csv.resolve())
    if analysis_json.exists() and "analysis_results_json" not in data_outputs:
        data_outputs["analysis_results_json"] = str(analysis_json.resolve())

    if chromatogram_png.exists() and "chromatogram_png" not in plots_outputs:
        plots_outputs["chromatogram_png"] = str(chromatogram_png.resolve())
    if chromatogram_pdf.exists() and "chromatogram_pdf" not in plots_outputs:
        plots_outputs["chromatogram_pdf"] = str(chromatogram_pdf.resolve())

    # Summary block
    meta_block = analysis.get("metadata") if isinstance(analysis.get("metadata"), dict) else {}
    peak_detection = meta_block.get("peak_detection") if meta_block else None
    num_peaks = meta_block.get("num_peaks") if meta_block else None
    files_processed = analysis.get("files_processed")
    message = analysis.get("message")

    summary = {
        "num_peaks": int(num_peaks) if isinstance(num_peaks, (int, float)) else None,
        "peak_detection": peak_detection,
        "files_processed": int(files_processed) if isinstance(files_processed, (int, float)) else None,
        "message": message,
    }

    # analysis_metadata retains the full original analysis metadata and helper fields
    analysis_metadata = {
        "experiment_id": analysis.get("experiment_id"),
        "raw_status": analysis.get("status"),
        "raw_message": analysis.get("message"),
        "metadata": analysis.get("metadata"),
        "files_processed": analysis.get("files_processed"),
    }

    return {
        "analysis_status": analysis_status,
        "analysis_timestamp": timestamp,
        "summary": summary,
        "analysis_metadata": analysis_metadata,
        "data_files": data_outputs,
        "plots": plots_outputs,
    }


# ============================================================================
# MAIN FUNCTIONS
# ============================================================================


def upsert_process_schema(cursor):
    """Insert or update process schema."""

    cursor.execute(
        """
        INSERT INTO process_schemas (
            process_id, process_name, version,
            metadata_schema, results_schema, field_mapping, expected_files
        ) VALUES (%s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (process_id) DO UPDATE SET
            process_name = EXCLUDED.process_name,
            metadata_schema = EXCLUDED.metadata_schema,
            results_schema = EXCLUDED.results_schema,
            field_mapping = EXCLUDED.field_mapping,
            expected_files = EXCLUDED.expected_files,
            updated_at = NOW()
        """,
        (
            PROCESS_ID,
            PROCESS_NAME,
            PROCESS_VERSION,
            json.dumps(METADATA_SCHEMA),
            json.dumps(RESULTS_SCHEMA),
            json.dumps(FIELD_MAPPING),
            json.dumps(EXPECTED_FILES),
        ),
    )


def upsert_experiment(cursor, elab_id, data):
    """Insert or update experiment execution."""

    cursor.execute(
        """
        INSERT INTO experiment_executions (
            elab_id, elab_title, process_id, process_name, lab_id,
            status, "user", workflow_json, metadata, raw_data, results
        ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (elab_id) DO UPDATE SET
            elab_title = EXCLUDED.elab_title,
            status = EXCLUDED.status,
            metadata = EXCLUDED.metadata,
            raw_data = EXCLUDED.raw_data,
            results = EXCLUDED.results,
            workflow_json = EXCLUDED.workflow_json,
            updated_at = NOW()
        RETURNING id
        """,
        (
            elab_id,
            data["title"],
            PROCESS_ID,
            PROCESS_NAME,
            data["lab_id"],
            data["status"],
            data["user"],
            json.dumps(data["workflow_json"]) if data["workflow_json"] is not None else None,
            json.dumps(data["metadata"]),
            json.dumps(data["raw_data"]),
            json.dumps(data["results"]),
        ),
    )
    row = cursor.fetchone()
    return row[0] if row else None


def main():
    parser = argparse.ArgumentParser(description=f"Commit {PROCESS_NAME} to database")
    parser.add_argument("elab_id", type=int, help="eLabFTW experiment ID")
    parser.add_argument("--dry-run", action="store_true", help="Don't commit, just show what would be done")
    parser.add_argument(
        "--init-schema-only",
        action="store_true",
        help="Only initialize process schema",
    )
    args = parser.parse_args()

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        # Always upsert schema
        upsert_process_schema(cursor)
        print(f"Process schema updated: {PROCESS_NAME} (ID: {PROCESS_ID})")

        if args.init_schema_only:
            conn.commit()
            print("Schema-only mode, skipping experiment data.")
            return 0

        # Load experiment data
        exp_json_path = find_experiment_json(args.elab_id)
        with open(exp_json_path) as f:
            exp_data = json.load(f)

        # Extract fields
        extra_fields = exp_data.get("metadata_decoded", {}).get("extra_fields", {}) or {}
        workflow_json, lab_id = load_workflow()

        # Build data structures
        metadata = extract_metadata(extra_fields)
        raw_data = build_raw_data(args.elab_id)
        results = build_results(args.elab_id)

        data = {
            "title": exp_data.get("title", ""),
            "lab_id": lab_id,
            "status": "completed",
            "user": exp_data.get("userid_human", ""),
            "workflow_json": workflow_json,
            "metadata": metadata,
            "raw_data": raw_data,
            "results": results,
        }

        if args.dry_run:
            print("DRY RUN - Would insert:")
            print(json.dumps(data, indent=2, default=str))
            conn.rollback()
            return 0

        # Commit to database
        exp_db_id = upsert_experiment(cursor, args.elab_id, data)
        conn.commit()

        print(f"Experiment {args.elab_id} committed successfully (DB ID: {exp_db_id})")
        return 0

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        if conn is not None:
            conn.rollback()
        return 1
    finally:
        if conn is not None:
            conn.close()


if __name__ == "__main__":
    sys.exit(main())
